solution:
function binarySearch(sortedNumbers, target) {
  let left = 0
  let right = sortedNumbers.length - 1
  while (left <= right) {
    const middle = Math.floor((left + right) / 2)
    if (sortedNumbers[middle] === target) return middle
    if (sortedNumbers[middle] < target) left = middle + 1
    else right = middle - 1
  }
  return -1
}

